+              🕒
+            </button>
+          </div>
+
+          {/* Calculator Display Screen */}
+          <div 
+            className="calculator-screen" 
+            ref={displayRef}
+            role="region"
+            aria-label="Calculator display screen"
+          >
+            {calculatorMode === "rpn" ? (
+              <div className="rpn-stack-display" aria-label="RPN Evaluation Stack">
+                <div className="stack-level" aria-label={`Stack Level T: ${rpnStack[rpnStack.length - 4] || "0"}`}>
+                  <span className="level-label">T:</span>
+                  <span className="level-value">{rpnStack[rpnStack.length - 4] || "0"}</span>
+                </div>
+                <div className="stack-level" aria-label={`Stack Level Z: ${rpnStack[rpnStack.length - 3] || "0"}`}>
+                  <span className="level-label">Z:</span>
+                  <span className="level-value">{rpnStack[rpnStack.length - 3] || "0"}</span>
+                </div>
+                <div className="stack-level" aria-label={`Stack Level Y: ${rpnStack[rpnStack.length - 2] || "0"}`}>
+                  <span className="level-label">Y:</span>
+                  <span className="level-value">{rpnStack[rpnStack.length - 2] || "0"}</span>
+                </div>
+                <div className={`stack-level active-level ${error ? "error-text" : ""}`} aria-label={`Stack Level X: ${expression || rpnStack[rpnStack.length - 1] || "0"}`}>
+                  <span className="level-label">X:</span>
+                  <span className="level-value">{expression || rpnStack[rpnStack.length - 1] || "0"}</span>
+                </div>
+                {error && <div className="stack-error-line" role="alert">{error}</div>}
+              </div>
+            ) : (
+              <>
+                <div 
+                  className="expression-line" 
+                  aria-label={`Current expression: ${expression || "Empty"}`}
+                >
+                  {expression || "0"}
+                </div>
+                <div 
+                  className={`result-line ${error ? "error-text" : ""}`}
+                  aria-label={error ? `Error: ${error}` : `Result: ${result || "0"}`}
+                >
+                  {error ? error : (result || "0")}
