    expect(screen.getByLabelText('Stack Level Y: 0')).toBeInTheDocument();
    expect(screen.getByLabelText('Stack Level Z: 0')).toBeInTheDocument();
    expect(screen.getByLabelText('Stack Level T: 0')).toBeInTheDocument();

